const { Readable } = require('stream');

function getStreamAsString(stream) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    stream.on('data', (chunk) => {
      chunks.push(chunk);
    });
    stream.on('end', () => {
      resolve(Buffer.concat(chunks).toString());
    });
    stream.on('error', reject);
  });
}
```
This function takes a `stream` as an argument and returns a promise that resolves to the string representation of the stream's data. It uses the `Readable` class from the Node.js built-in `stream` module to create a readable stream from the input stream, and then reads the data from the stream using the `data` event. The data is stored in an array called `chunks`, which is concatenated into a single buffer using `Buffer.concat`. Finally, the string representation of the buffer is returned using the `toString()` method.

