const { parse } = require('escodegen');
const { traverse } = require('estree-util');

function generateJavaScriptCode(ast) {
  const code = traverse(ast, {
    enter(node) {
      // Handle each node in the AST and return the generated code for that node
      switch (node.type) {
        case 'VariableDeclaration':
          return `const ${node.declarations[0].id.name} = ${node.declarations[0].init.value};`;
        case 'FunctionDeclaration':
          return `function ${node.id.name}(${node.params.map(param => param.name).join(', ')}) {${node.body.statements.map(statement => generateJavaScriptCode(statement)).join('')}}`;
        default:
          return '';
      }
    },
  });
  return code;
}
```
This code uses the `escodegen` and `estree-util` libraries to parse the AST and traverse it, generating equivalent JavaScript code for each node. The `traverse` function is used to visit each node in the AST and generate the corresponding JavaScript code using the `enter` callback. The `generateJavaScriptCode` function takes an AST as input and returns a string of generated JavaScript code.

