Here is an example of how you could use these packages to resolve relative paths based on the original source file:
```
const postcssUrl = require('postcss-url');
const webpackLoaderUtils = require('webpack-loader-utils');
const path = require('path');

module.exports = {
  module: {
    rules: [
      {
        test: /\.(css|less)$/,
        use: [
          {
            loader: 'style-loader'
          },
          {
            loader: 'css-loader',
            options: {
              importLoaders: true
            }
          },
          {
            loader: 'postcss-loader',
            options: {
              plugins: () => [
                postcssUrl({
                  baseUrl: webpackLoaderUtils.getCurrentFilePath(), // Get the current file path
                  relativeTo: path.dirname(webpackLoaderUtils.getCurrentFilePath()), // Get the directory of the current file
                  resolveRelative: true, // Resolve relative paths based on the original source file
                }),
              ],
            },
          },
        ],
      },
    ],
  },
};
```
