const parseMetadata = require('npm-manifest-parser');

const metadata = parseMetadata(packageMetaDataDocument);
const version = metadata.version;
const dependencies = metadata.dependencies;

// Use semver to resolve the highest version that satisfies the dependency constraints
const resolvedVersion = semver.maxSatisfying(Object.keys(dependencies), version, { loose: true });

// Return the resolved manifest
