```
const webpack = require('webpack');
const TreemapVisualizerPlugin = require('treemap-visualizer-plugin');

// Create a new Webpack plugin that uses the TreemapVisualizerPlugin
class BundleVisualizerPlugin extends webpack.Plugin {
  constructor(options) {
    super();
    this.options = options;
  }

  apply(compiler) {
    compiler.hooks.emit.tap('BundleVisualizerPlugin', (compilation, callback) => {
      const treemap = new TreemapVisualizerPlugin({
        // Set the output directory for the treemap visualization
        outputDir: this.options.outputDir || 'treemap-visualization',
        // Set the filename for the treemap visualization
        filename: this.options.filename || 'bundle-treemap.html',
      });

      // Add the TreemapVisualizerPlugin to the compilation
      compilation.plugins.push(treemap);

      callback();
    });
  }
}

// Create a new CLI utility that uses the BundleVisualizerPlugin
const BundleVisualizerCLI = {
  run: (args) => {
    const options = args.options || {};
    const compiler = webpack(options);
    const treemap = new TreemapVisualizerPlugin({
      // Set the output directory for the treemap visualization
      outputDir: options.outputDir || 'treemap-visualization',
      // Set the filename for the treemap visualization
      filename: options.filename || 'bundle-treemap.html',
    });

    compiler.hooks.emit.tap('BundleVisualizerCLI', (compilation, callback) => {
      compilation.plugins.push(treemap);
      callback();
    });
  },
};
```
This code creates a new Webpack plugin called `BundleVisualizerPlugin` that uses the `TreemapVisualizerPlugin` to generate a treemap visualization of the bundle contents. The plugin can be added to a Webpack configuration file using the `plugins` property, and it will automatically generate a treemap visualization for each compilation.

The CLI utility called `BundleVisualizerCLI` can also be used to generate a treemap visualization for a specific bundle. It takes an options object as input, which can contain properties such as the output directory and filename for the treemap visualization. The CLI utility uses the same `TreemapVisualizerPlugin` as the Webpack plugin, but it is not added to the Webpack configuration file. Instead, it is run manually using the `webpack` command with the appropriate options.

For example, to generate a treemap visualization for the bundle in the current directory and save it to the `treemap-visualization` directory with the filename `bundle-treemap.html`, you can use the following command:
```
webpack --plugin BundleVisualizerPlugin --outputDir treemap-visualization --filename bundle-treemap.html
```

