```
// Create a new ESLint plugin for testing library
const TestingLibraryPlugin = {
  meta: {
    type: 'suggestion',
    docs: {
      description: 'Enforce best practices and detect common mistakes in test files using Testing Library'
    },
    fixable: 'code',
    schema: []
  },
  create(context) {
    return {
      // Custom rules for testing library
      'CallExpression[callee.name="render"]': (node) => {
        if (!node.arguments || node.arguments.length !== 1) {
          context.report({
            node,
            message: 'Expected a single argument to be passed to render()'
          });
        }
      },
      'CallExpression[callee.name="fireEvent"]': (node) => {
        if (!node.arguments || node.arguments.length !== 2) {
          context.report({
            node,
            message: 'Expected two arguments to be passed to fireEvent()'
          });
        }
      },
      // Custom fixes for testing library
      'CallExpression[callee.name="render"]': (node) => {
        const arg = node.arguments[0];
        if (arg.type === 'ObjectExpression') {
          context.report({
            node,
            message: 'Expected a single argument to be passed to render()',
            fix(fixer) {
              return fixer.replaceText(node, `render(${arg.properties[0].value})`);
            }
          });
        }
      },
      'CallExpression[callee.name="fireEvent"]': (node) => {
        const arg1 = node.arguments[0];
        const arg2 = node.arguments[1];
        if (arg1.type === 'ObjectExpression' && arg2.type === 'StringLiteral') {
          context.report({
            node,
            message: 'Expected two arguments to be passed to fireEvent()',
            fix(fixer) {
              return fixer.replaceText(node, `fireEvent(${arg1.properties[0].value}, ${arg2.value})`);
            }
          });
        }
      }
    };
  }
};

