// Using es2015-generator-utils library
const { asyncToGenerator } = require('es2015-generator-utils');

// Define an asynchronous generator function
async function* myAsyncGen() {
  yield 'Hello';
  yield 'World';
}

// Convert the asynchronous generator function to an ES2015 generator
const myGen = asyncToGenerator(myAsyncGen);

