const webpack = require('webpack');
const angularCompilerCli = require('angular-compiler-cli');

class AotPlugin {
  constructor(options) {
    this.options = options;
  }

  apply(compiler) {
    compiler.hooks.emit.tapAsync('AotPlugin', (compilation, callback) => {
      const angularCompilerOptions = {
        ...this.options,
        entryModule: compilation.entryModule,
      };

      angularCompilerCli.compile(angularCompilerOptions).then((result) => {
        const compiledCode = result.code;
        const bundleFile = compilation.assets[compilation.entryModule];

        // Inject the compiled code into the main bundle file
        bundleFile.source().replace('<insert-compiled-code>', compiledCode);

        callback();
      });
    });
  }
}

module.exports = AotPlugin;
```
This code creates a Webpack plugin using the `webpack-plugin` module, which uses the `angular-compiler-cli` package to perform AoT compilation of Angular components and modules. The plugin injects the compiled code into the main bundle file.

The `AotPlugin` class is defined with a constructor that takes an options object as input. The options object can contain any configuration options for the AoT compiler, such as the entry module to compile.

In the `apply` method of the plugin, we use the `tapAsync` hook to intercept the `emit` event of the Webpack compilation process. This allows us to modify the output bundle file before it is written to disk.

We then use the `angularCompilerCli.compile` function to perform AoT compilation of the entry module, passing in any configuration options that were provided in the constructor. The `compile` function returns a promise that resolves with an object containing the compiled code and other metadata.

Once we have the compiled code, we can inject it into the main bundle file using the `replace` method of the `bundleFile` object. This replaces the `<insert-compiled-code>` placeholder in the bundle file with the actual compiled code.

Finally, we call the `callback` function to indicate that the plugin has finished processing the compilation.

```
const webpack = require('webpack');
const angularCompilerCli = require('angular-compiler-cli');

class AotPlugin {
  constructor(options) {
    this.options = options;
  }

  apply(compiler) {
    compiler.hooks.emit.tapAsync('AotPlugin', (compilation, callback) => {
      const angularCompilerOptions = {
        ...this.options,
        entryModule: compilation.entryModule,
        outputPath: compilation.outputPath,
      };

      angularCompilerCli.compile(angularCompilerOptions).then((result) => {
        // Inject the compiled code into the main bundle file
        const bundleFile = compilation.assets[compilation.mainTemplate];
        const compiledCode = result.code;
        const newBundleFile = bundleFile.source().replace(/(\/\*.*\*\/)?\s*angular\.module/, `/* ${result.name} */ angular.module`);
        compilation.assets[compilation.mainTemplate] = {
          source: () => newBundleFile,
          size: () => newBundleFile.length,
        };
      }).catch((error) => {
        console.log(error);
      });
    });
  }
}

module.exports = AotPlugin;
```
This code defines a `AotPlugin` class that extends the `webpack.Plugin` class and overrides its `apply` method to perform AoT compilation of Angular components and modules using the `angular-compiler-cli` package. The plugin takes an options object as input, which can contain any configuration options for the AoT compiler.

The `apply` method first retrieves the entry module from the `compilation` object and passes it to the `angularCompilerCli.compile` function along with any additional configuration options specified in the `options` object. The `compile` function returns a promise that resolves with an object containing the compiled code and other metadata.

Once the compilation is complete, the plugin injects the compiled code into the main bundle file using the `compilation.assets[compilation.mainTemplate]` property. This property contains the contents of the main bundle file as a string, which we can modify by replacing the `angular.module` declaration with the compiled code. The new bundle file is then returned as an asset in the `compilation.assets` object.

Note that this plugin assumes that the Angular components and modules are located in the same directory as the main bundle file. If your project structure is different, you may need to adjust the path to the entry module accordingly.

