// Import the necessary modules
const { readFileSync } = require('fs');
const { createRequire } = require('module');
const { WebAssembly } = require('webassembly-js');

// Create a shim for esbuild on Android x64
const esbuildShim = (input, options) => {
  // Load the esbuild wasm module
  const wasmModule = readFileSync(require.resolve('esbuild/esbuild.wasm'), 'utf8');
  const wasmInstance = new WebAssembly.Instance(new WebAssembly.Module(wasmModule));

  // Call the esbuild function with the input and options
  return wasmInstance.exports.build(input, options);
};

// Export the shim as a function that can be called by the host application
module.exports = {
  esbuildShim: esbuildShim
};
