const ast = sassParser.parseFile(filePath);

// Create an empty graph to store the imports
const graph = new Graph();

// Traverse the AST and create nodes for each import statement
ast.forEach((node) => {
  if (node.type === 'import') {
    const importNode = new Node(node.value);
    graph.addNode(importNode);
  }
});

