import { Trie } from 'javascript-trie';

function createUnicodeTrie(inputString) {
  const trie = new Trie();
  for (let i = 0; i < inputString.length; i++) {
    const charCode = inputString.charCodeAt(i);
    if (!trie.has(charCode)) {
      trie.set(charCode, {});
    }
    const charData = trie.get(charCode);
    charData[inputString[i]] = true;
  }
  return trie;
}

function getCodePoint(trie, character) {
  return trie.has(character) ? character : null;
}

function getName(trie, codePoint) {
  const charData = trie.get(codePoint);
  return charData && charData.name ? charData.name : null;
}

function getCategory(trie, codePoint) {
  const charData = trie.get(codePoint);
  return charData && charData.category ? charData.category : null;
}

export { createUnicodeTrie, getCodePoint, getName, getCategory };
