// Import required modules and libraries
const icu = require('icu-js');
const Trie = require('javascript-trie');

// Create function to create Unicode Trie data structure from string input
function createUnicodeTrie(inputString) {
  // Initialize trie object with empty array
  const trie = new Trie();

  // Iterate over each character in the input string
  for (let i = 0; i < inputString.length; i++) {
    // Get current character and its code point
    const char = inputString[i];
    const codePoint = icu.getCodePoint(char);

    // Add character to trie object, creating new nodes as needed
    trie.add(codePoint, char);
  }

  return trie;
}

// Implement trie data structure using nested array format
class UnicodeTrie {
  constructor() {
    this.root = [];
  }

  add(codePoint, char) {
    // Get current node in the tree
    let currentNode = this.root;

    // Iterate over each digit of the code point
    for (let i = 0; i < codePoint.length; i++) {
      const digit = codePoint[i];

      // Create new node if it doesn't exist yet
      if (!currentNode[digit]) {
        currentNode[digit] = [];
      }

      // Move to next node in the tree
      currentNode = currentNode[digit];
    }

    // Add character to current node
    currentNode.push(char);
  }

  get(codePoint) {
    // Get current node in the tree
    let currentNode = this.root;

    // Iterate over each digit of the code point
    for (let i = 0; i < codePoint.length; i++) {
      const digit = codePoint[i];

      // Move to next node in the tree if it exists
      if (currentNode[digit]) {
        currentNode = currentNode[digit];
      } else {
        return null;
      }
    }

    // Return character at current node
    return currentNode.pop();
  }
}

// Add methods to trie object for fast lookups of various types of character metadata
UnicodeTrie.prototype.getCodePoint = function(char) {
  const codePoint = icu.getCodePoint(char);
  return codePoint;
};

UnicodeTrie.prototype.getName = function(codePoint) {
  const name = icu.getName(codePoint);
  return name;
};

UnicodeTrie.prototype.getCategory = function(codePoint) {
  const category = icu.getCategory(codePoint);
  return category;
};

// Export trie object as a module that can be imported and used in other JavaScript projects
module.exports = UnicodeTrie;
