```
// node-debugging-tools.js

const { inspect } = require('util');
const { EventEmitter } = require('events');

class Debugger extends EventEmitter {
  constructor() {
    super();
    this.activeHandles = [];
    this.eventLoopMonitor = null;
    this.profiler = null;
  }

  startEventLoopMonitor() {
    if (this.eventLoopMonitor) return;
    this.eventLoopMonitor = setInterval(() => {
      const activeHandles = process.getActiveHandles();
      this.activeHandles = activeHandles;
      this.emit('eventLoopTick', activeHandles);
    }, 1000);
  }

  stopEventLoopMonitor() {
    if (!this.eventLoopMonitor) return;
    clearInterval(this.eventLoopMonitor);
    this.eventLoopMonitor = null;
  }

  startProfiler() {
    if (this.profiler) return;
    this.profiler = new Profiler();
    this.profiler.start();
  }

  stopProfiler() {
    if (!this.profiler) return;
    this.profiler.stop();
    this.profiler = null;
  }
}

class Profiler {
  constructor() {
    this.startTime = Date.now();
    this.endTime = null;
    this.samples = [];
  }

  start() {
    this.endTime = null;
    this.samples = [];
  }

  stop() {
    this.endTime = Date.now();
    const duration = this.endTime - this.startTime;
    const averageSample = this.samples.reduce((a, b) => a + b, 0) / this.samples.length;
    console.log(`Profiler: ${duration}ms (${averageSample}ms/sample)`);
  }

  addSample(time) {
    if (this.endTime) return;
    this.samples.push(time - this.startTime);
  }
}

module.exports = {
  Debugger,
  Profiler,
};
```
This code creates a module called `node-debugging-tools` that exports two classes: `Debugger` and `Profiler`. The `Debugger` class is an event emitter that provides functions for debugging node.js modules and the event loop. It has three methods:

* `startEventLoopMonitor()`: Starts monitoring the event loop by calling `setInterval()` to check for active handles every 1000 milliseconds.
* `stopEventLoopMonitor()`: Stops monitoring the event loop by clearing the interval.
* `startProfiler()`: Starts a profiler that measures the time spent in each handle.
* `stopProfiler()`: Stops the profiler and logs the results to the console.

The `Profiler` class is used to measure the performance of node.js modules. It has three methods:

* `start()`: Starts measuring the time spent in each handle.
* `stop()`: Stops measuring the time spent in each handle and logs the results to the console.
* `addSample(time)`: Adds a sample of the current time to the profiler's list of samples.

The `node-debugging-tools` module can be used as follows:
```
const { Debugger, Profiler } = require('node-debugging-tools');

// Create a new debugger instance
const dbg = new Debugger();

// Start monitoring the event loop
dbg.startEventLoopMonitor();

// Start profiling performance
dbg.startProfiler();

// Do some work
for (let i = 0; i < 1000000; i++) {
  // ...
}

// Stop profiling performance
dbg.stopProfiler();

// Stop monitoring the event loop
dbg.stopEventLoopMonitor();
```

