const metroTransform = require('metro-transform');

// Define a function to transform React components into optimized, server-side rendered HTML strings
function transformReactComponents(components) {
  // Use Metro's bundling and optimization capabilities to generate an optimized bundle of the provided React components
  const optimizedBundle = metroTransform.bundle({
    entryPoints: components,
    minify: true,
    optimize: true,
  });

  // Extract the HTML string from the optimized bundle
  const htmlString = optimizedBundle.toString();

  return htmlString;
}
