const { TextMapPropagator } = require('opentelemetry-propagator-jaeger');

const propagator = new TextMapPropagator();

function injectHeaders(headers) {
  const carrier = {};
  propagator.inject(carrier, headers);
  return carrier;
}

function extractHeaders(headers) {
  const carrier = {};
  propagator.extract(carrier, headers);
  return carrier;
}
```
This code creates an instance of the OpenTelemetry Jaeger propagator and defines two functions: `injectHeaders` and `extractHeaders`. The `injectHeaders` function takes an object containing HTTP headers as input and uses the Jaeger propagator to inject trace information into the headers in the Jaeger HTTP header format. The `extractHeaders` function takes an object containing HTTP headers as input and uses the Jaeger propagator to extract trace information from the headers in the Jaeger HTTP header format.

To use these functions, you can call them with an object containing your HTTP headers as input, like this:
```
const headers = { 'x-trace-id': '1234567890abcdef' };
