```
import { graphql } from 'graphql';
import { GraphQLObjectType, GraphQLList, GraphQLString } from 'graphql-js-tag';

const Book = new GraphQLObjectType({
  name: 'Book',
  fields: () => ({
    id: { type: GraphQLString },
    title: { type: GraphQLString },
    author: { type: GraphQLString },
  }),
});

const Query = new GraphQLObjectType({
  name: 'Query',
  fields: () => ({
    books: {
      type: new GraphQLList(Book),
      resolve: async (parent, args) => {
        const response = await fetch('https://fake-api.com/books');
        return response.json();
      },
    },
  }),
});

const Mutation = new GraphQLObjectType({
  name: 'Mutation',
  fields: () => ({
    createBook: {
      type: Book,
      args: {
        title: { type: GraphQLString },
        author: { type: GraphQLString },
      },
      resolve: async (parent, { title, author }) => {
        const response = await fetch('https://fake-api.com/books', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ title, author }),
        });
        return response.json();
      },
    },
    updateBook: {
      type: Book,
      args: {
        id: { type: GraphQLString },
        title: { type: GraphQLString },
        author: { type: GraphQLString },
      },
      resolve: async (parent, { id, title, author }) => {
        const response = await fetch(`https://fake-api.com/books/${id}`, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ title, author }),
        });
        return response.json();
      },
    },
    deleteBook: {
      type: Book,
      args: { id: { type: GraphQLString } },
      resolve: async (parent, { id }) => {
        const response = await fetch(`https://fake-api.com/books/${id}`, { method: 'DELETE' });
        return response.json();
      },
    },
  }),
});

const schema = new GraphQLSchema({ query: Query, mutation: Mutation });
```
This code creates a GraphQL schema using the `graphql-tag` and `graphql-js-tag` packages. The schema includes a query type that retrieves a list of books from a fake API, and a mutation type that allows for creating, updating, and deleting book objects. The `Book` type is defined as an object with three fields: `id`, `title`, and `author`. The `Query` type includes a field called `books` that returns a list of `Book` objects. The `Mutation` type includes fields for creating, updating, and deleting book objects. Each field has a corresponding resolver function that makes an HTTP request to the fake API using the `fetch` function.

```
const { gql } = require('graphql-tag');
const { GraphQLObjectType, GraphQLList, GraphQLString } = require('graphql-js-tag');

const BookType = new GraphQLObjectType({
  name: 'Book',
  fields: () => ({
    id: { type: GraphQLString },
    title: { type: GraphQLString },
    author: { type: GraphQLString },
  }),
});

const QueryType = new GraphQLObjectType({
  name: 'Query',
  fields: () => ({
    books: {
      type: new GraphQLList(BookType),
      resolve: (root, args) => {
        // Fake API call to retrieve a list of books
        const books = [
          { id: '1', title: 'Book 1', author: 'Author 1' },
          { id: '2', title: 'Book 2', author: 'Author 2' },
          { id: '3', title: 'Book 3', author: 'Author 3' },
        ];
        return books;
      },
    },
  }),
});

const MutationType = new GraphQLObjectType({
  name: 'Mutation',
  fields: () => ({
    createBook: {
      type: BookType,
      args: {
        title: { type: GraphQLString },
        author: { type: GraphQLString },
      },
      resolve: (root, args) => {
        // Fake API call to create a new book object
        const book = { id: '4', title: args.title, author: args.author };
        return book;
      },
    },
    updateBook: {
      type: BookType,
      args: {
        id: { type: GraphQLString },
        title: { type: GraphQLString },
        author: { type: GraphQLString },
      },
      resolve: (root, args) => {
        // Fake API call to update a book object
        const book = { id: args.id, title: args.title, author: args.author };
        return book;
      },
    },
    deleteBook: {
      type: BookType,
      args: {
        id: { type: GraphQLString },
      },
      resolve: (root, args) => {
        // Fake API call to delete a book object
        const book = { id: args.id };
        return book;
      },
    },
  }),
});

const schema = new GraphQLSchema({
  query: QueryType,
  mutation: MutationType,
});
```
This code defines a GraphQL schema with a `Query` type that retrieves a list of books from a fake API and a `Mutation` type that allows for creating, updating, and deleting book objects. The `Book` type is defined as an object with fields for the book's ID, title, and author. The `Query` and `Mutation` types are defined using the `GraphQLObjectType` class from the `graphql-js-tag` package. The `resolve` function of each field in the `Query` type is used to retrieve a list of books from a fake API, while the `resolve` functions of each field in the `Mutation` type are used to create, update, and delete book objects.

