const webpackPerf = require('webpack-perf');

// Set up the Webpack configuration
const config = {
  entry: './src/index.js',
  output: {
    path: __dirname + '/dist',
    filename: 'bundle.js'
  },
  module: {
    rules: [
      {
        test: /\.css$/,
        use: ['style-loader', 'css-loader']
      }
    ]
  },
  plugins: [
    new webpackPerf.Plugin()
  ]
};

// Run Webpack with the performance plugin enabled
webpack(config, (err, stats) => {
  if (err || stats.hasErrors()) {
    console.log('Webpack build failed');
  } else {
    // Get the performance data from the plugin
    const perfData = webpackPerf.getData();

    // Calculate and display statistics for each loader or plugin
    perfData.forEach((data) => {
      const totalTime = data.totalTime;
      const overhead = data.overhead;
      const sizeGaps = data.sizeGaps;

      console.log(`Loader/Plugin: ${data.name}`);
      console.log(`Total time: ${totalTime}ms`);
      console.log(`Overhead: ${overhead}ms`);
      console.log(`Size gaps: ${sizeGaps}`);
    });
  }
});
```
This code sets up a Webpack configuration with the `webpack-perf` plugin enabled, which collects performance data for each loader and plugin during the build process. The `webpack-perf` plugin provides detailed information about the time spent in each loader or plugin, including total time, overhead, and size gaps.

