const prettier = require('prettier');
const { stableSort } = require('stable-sort');

function sortTailwindClasses(file) {
  const classes = file.match(/[a-zA-Z0-9_-]+/g);
  const sortedClasses = stableSort(classes, (a, b) => {
    if (a.startsWith('utility') && !b.startsWith('utility')) return -1;
    if (!a.startsWith('utility') && b.startsWith('utility')) return 1;
    if (a.startsWith('component') && !b.startsWith('component')) return -1;
    if (!a.startsWith('component') && b.startsWith('component')) return 1;
    return a.localeCompare(b);
  });
  return sortedClasses.join('\n');
}

module.exports = { sortTailwindClasses };
```
This code defines a function `sortTailwindClasses` that takes a file as input and returns the sorted Tailwind CSS classes within that file, using the stable sort algorithm to ensure that the original order of each group is preserved. The function first matches all the Tailwind CSS class names in the file using a regular expression, then sorts them using the `stableSort` function from the `stable-sort` library.

The sorting algorithm uses the following criteria:

1. If both classes are utility classes (i.e., they start with "utility"), sort them alphabetically.
2. If one class is a utility class and the other is not, sort the non-utility class first.
3. If both classes are component classes (i.e., they start with "component"), sort them alphabetically.
4. Otherwise, sort the classes alphabetically.

The `stableSort` function ensures that the original order of each group is preserved, even if the sorting algorithm reorders some of the classes within a group. This is important because Tailwind CSS classes are often used in a specific order to achieve a desired layout or design.

Finally, the function returns the sorted class names as a string, with each class name separated by a newline character (`\n`).

