Here is an example of how you could create a modern, fast, and powerful web framework using Node.js and GraphQL:
```
const express = require('express');
const graphqlHTTP = require('express-graphql');

// Create a new Express app
const app = express();

// Define the schema for our GraphQL API
const typeDefs = `
  type Query {
    hello: String!
  }
`;

// Define the resolvers for our GraphQL API
const resolvers = {
  Query: {
    hello: () => 'Hello, world!'
  }
};

// Create a new GraphQL schema using the type definitions and resolvers
const schema = makeExecutableSchema({ typeDefs, resolvers });

// Use the GraphQL middleware to handle incoming requests
app.use('/graphql', graphqlHTTP({ schema }));

// Start the server
app.listen(3000, () => {
  console.log('Server started on port 3000');
});
```
