function encodeCMSSignedData(data) {
  // Use the appropriate CMS encoder based on the data type
  if (typeof data === 'string') {
    return cms.encodeString(data);
  } else if (typeof data === 'number') {
    return cms.encodeNumber(data);
  }
}

