function encodeTimeStamp(data) {
  // Use the appropriate TimeStamp encoder based on the data type
  if (typeof data === 'string') {
    return timestamp.encodeString(data);
  } else if (typeof data === 'number') {
    return timestamp.encodeNumber(data);
  }
}

