function encodeCAdES(data) {
  // Use the appropriate CAdES encoder based on the data type
  if (typeof data === 'string') {
    return cadese.encodeString(data);
  } else if (typeof data === 'number') {
    return cadese.encodeNumber(data);
  }
}

function decodeCAdES(data) {
