  if (typeof data === 'string') {
    return cadese.decodeString(data);
  } else if (typeof data === 'number') {
    return cadese.decodeNumber(data);
  }
}

// JSON Web Signature(JWS)/Token(JWT)/Key(JWK) encoding/decoding
