import { google } from '@google-cloud/proto-files';

const protoFiles = google.protos;

// Organize the protocol buffer files into a neat and tidy structure
const organizedProtoFiles = {};
for (const file of protoFiles) {
  const [packageName, fileName] = file.split('/');
  if (!organizedProtoFiles[packageName]) {
    organizedProtoFiles[packageName] = [];
  }
  organizedProtoFiles[packageName].push(fileName);
}
