const config = {};

// Load configuration from package.json
if (fs.existsSync('package.json')) {
  const packageJson = JSON.parse(fs.readFileSync('package.json'));
  if (packageJson.config) {
    Object.assign(config, packageJson.config);
  }
}

// Load configuration from rc file
if (fs.existsSync('.rc')) {
  const rc = JSON.parse(fs.readFileSync('.rc'));
  if (rc.config) {
    Object.assign(config, rc.config);
  }
}

// Load configuration from TypeScript module
if (fs.existsSync('typescript-module')) {
  const typescriptModule = require('typescript-module');
  if (typescriptModule.config) {
    Object.assign(config, typescriptModule.config);
  }
}

// Load configuration from other sources
// ...

console.log(config);
```
This code uses the `fs` module to check for the existence of a `package.json`, `.rc` file, and `typescript-module`. If any of these files exist, it loads their contents using `JSON.parse()` and merges them with the existing configuration object using `Object.assign()`. The resulting configuration object is then logged to the console.

Note that this code assumes that the configuration files are in JSON format and that they contain a top-level `config` property. If your configuration files have different formats or structures, you may need to modify the code accordingly.

