const myArray = [1, 2, 3];
const myObject = { a: 1, b: 2 };
const myFunction = (x) => x * 2;

console.log(array.map(myArray, (element) => element * 2)); // Output: [2, 4, 6]
console.log(object.keys(myObject)); // Output: ["a", "b"]
