const { SSOLogin } = require('node-sso-login');
const { Credentials } = require('aws-sdk');

const ssoLogin = new SSOLogin({
  clientId: 'your_client_id',
  clientSecret: 'your_client_secret',
  region: 'your_region'
});

async function getAWSCredentials() {
  const tokenFilePath = '/path/to/token.json';
  const token = await ssoLogin.getToken(tokenFilePath);
  const credentials = new Credentials({
    accessKeyId: token.access_key,
    secretAccessKey: token.secret_key,
    sessionToken: token.session_token,
    expiration: token.expires_at
  });
  return credentials;
}
```
This code creates an AWS credential provider that reads a resolved SSO login token file and returns temporary AWS credentials using the `node-sso-login` library. The `SSOLogin` class is used to get the token from the token file, and the `Credentials` class is used to create the temporary AWS credentials.

The `getAWSCredentials` function is an async function that reads the token file and returns the temporary AWS credentials. It uses the `ssoLogin.getToken()` method to get the token from the token file, and then creates a new `Credentials` object with the token information. The `expiration` property of the `Credentials` object is set to the expiration time of the token, which is calculated based on the `expires_at` field in the token response.

To use this credential provider, you can pass it to the AWS SDK constructor like this:
```
