// node-crypto-signing.js
const crypto = require('crypto');

class CryptoSigner {
  constructor(key) {
    this.key = key;
  }

  sign(data) {
    return crypto.subtle.sign({ name: 'RSASSA-PKCS1-v1_5' }, this.key, data);
  }
}

module.exports = CryptoSigner;
```
This code creates a Node.js module that provides cryptographic signing functionality for browsers using the Web Cryptography API. The `CryptoSigner` class takes an RSA key as its constructor argument and provides a `sign()` method that can be used to sign data using the RSASSA-PKCS1-v1_5 algorithm.

To use this module in a web application, developers can import it and create a new instance of the `CryptoSigner` class with their RSA key. They can then use the `sign()` method to sign data and verify its integrity using the Web Cryptography API.

For example:
```
const crypto = require('crypto');
const { CryptoSigner } = require('node-crypto-signing');

// Generate a new RSA key pair
const keyPair = crypto.generateKeyPairSync('rsa', { modulusLength: 2048 });

// Create a new instance of the CryptoSigner class with the public key
const signer = new CryptoSigner(keyPair.publicKey);

// Sign some data
const signedData = signer.sign('Hello, world!');

// Verify the signature using the Web Cryptography API
const verified = crypto.subtle.verify({ name: 'RSASSA-PKCS1-v1_5' }, keyPair.publicKey, signedData);
console.log(verified); // Output: true
```

