```
const fs = require('fs');
const path = require('path');
const { parse } = require('json-parse-help');

function readPackageJson(filePath) {
  const fileContent = fs.readFileSync(filePath, 'utf8');
  const jsonObj = JSON.parse(fileContent);
  const schema = {
    type: 'object',
    properties: {
      name: { type: 'string' },
      version: { type: 'string' },
      description: { type: 'string' },
      dependencies: {
        type: 'array',
        items: {
          type: 'object',
          properties: {
            name: { type: 'string' },
            version: { type: 'string' }
          }
        }
      }
    }
  };
  const validationResult = parse(jsonObj, schema);
  if (validationResult.valid) {
    return jsonObj;
  } else {
    throw new Error(`Invalid package.json file: ${validationResult.errors}`);
  }
}
```
This code uses the `fs` and `path` modules to read the contents of a `package.json` file, parses it as JSON using the `JSON.parse()` method, and then validates its syntax against a JSON schema using the `parse()` function from the `json-parse-help` module. If the validation is successful, the parsed metadata and dependencies are returned in an object. Otherwise, an error is thrown with a message indicating what was invalid about the file.

