Note that the `define()` function can also be used to define modules that depend on other modules. For example:
```
define(["require", "exports", "otherModule"], function (require, exports) {
    var myModule = {};
    myModule.doSomething = function () {
        console.log("Hello from myModule!");
        require("otherModule").doSomethingElse();
    };
    return myModule;
});
```
