```
const { traverse } = require('ast-traverse');
const { manipulate } = require('ast-manipulate');
const { transform } = require('ast-transform');
const { filter } = require('ast-filter');

// Utility library for AST nodes
const astUtil = {
  // Traverses an AST node and its children, calling the provided callback function on each node
  traverse: (node, callback) => {
    if (!node || !callback) return;
    const visit = (node) => {
      callback(node);
      if (node.children) {
        node.children.forEach((child) => visit(child));
      }
    };
    visit(node);
  },

  // Manipulates an AST node and its children, modifying the provided node and returning a new copy of the modified tree
  manipulate: (node, callback) => {
    if (!node || !callback) return;
    const visit = (node) => {
      const newNode = callback(node);
      if (newNode !== node && newNode.children) {
        newNode.children = newNode.children.map((child) => visit(child));
      }
      return newNode;
    };
    return visit(node);
  },

  // Transforms an AST node and its children, modifying the provided node and returning a new copy of the modified tree
  transform: (node, callback) => {
    if (!node || !callback) return;
    const visit = (node) => {
      const newNode = callback(node);
      if (newNode !== node && newNode.children) {
        newNode.children = newNode.children.map((child) => visit(child));
      }
      return newNode;
    };
    return visit(node);
  },

  // Filters an AST node and its children, returning a new copy of the filtered tree
  filter: (node, callback) => {
    if (!node || !callback) return;
    const visit = (node) => {
      const newNode = callback(node);
      if (newNode !== node && newNode.children) {
        newNode.children = newNode.children.filter((child) => visit(child));
      }
      return newNode;
    };
    return visit(node);
  },

  // Adds a plugin to the utility library, allowing for additional functionality to be added
  addPlugin: (plugin) => {
    if (!plugin || !plugin.name || !plugin.callback) return;
    const { name, callback } = plugin;
    astUtil[name] = (node) => {
      if (!node) return;
      const newNode = callback(node);
      if (newNode !== node && newNode.children) {
        newNode.children = newNode.children.map((child) => visit(child));
      }
      return newNode;
    };
  },
};

// Exports the utility library for AST nodes
module.exports = astUtil;
```
This code defines a utility library for working with AST nodes in JavaScript, similar to Lodash-esque utility libraries like Babel Types. The library provides functions for traversing, manipulating, and transforming AST nodes, as well as filtering and adding plugins for additional functionality.

