const { TestRunner } = require('@testing-library/node');

class FastTestRunner extends TestRunner {
  constructor() {
    super();
    this.use(require('@testing-library/jest-dom'));
    this.use(require('@testing-library/react'));
    this.use(require('@testing-library/angular'));
    this.use(require('@testing-library/vue'));
  }

  async runTests() {
    const tests = await this.getTests();
    for (const test of tests) {
      try {
        await test.run();
      } catch (error) {
        console.log(error);
      }
    }
  }
}
