Here is an example of how you can create a facade to simplify the usage of Webpack:
```
// webpack-facade.js
const path = require('path');
const fs = require('fs');

module.exports = {
  build: function(config) {
    const configPath = path.resolve(__dirname, 'webpack.config.js');
    const outputPath = path.resolve(__dirname, 'dist');
    const webpackConfig = JSON.parse(fs.readFileSync(configPath));
    webpackConfig.output.path = outputPath;
    return new Promise((resolve, reject) => {
      webpack(webpackConfig, (err, stats) => {
        if (err) {
          reject(err);
        } else {
          resolve(stats);
        }
      });
    });
  }
};
```
This facade provides a simple API for building your Angular application with Webpack. It takes a configuration object as an argument, which is used to configure the Webpack build process. The `build` method returns a promise that resolves when the build process is complete, and rejects if there are any errors during the build process.

To use this facade, you can import it in your Angular application and call the `build` method with the desired configuration:
```
const webpackFacade = require('webpack-facade');

webpackFacade.build({
  entry: './src/index.js',
  output: {
    filename: 'bundle.js',
    path: path.resolve(__dirname, 'dist')
  },
  module: {
    rules: [
      {
        test: /\.js$/,
        use: 'babel-loader'
      }
    ]
  }
}).then((stats) => {
  console.log(stats);
});
```
