const sassParser = require('sass-parse');

// Parse the Sass file using the sass-parse library
const ast = sassParser.parseFile(filePath);

// Create a directed graph to represent the import relationships between the Sass files
const graph = new DirectedGraph();

// Traverse the AST and create nodes for each import statement
ast.forEach((node) => {
  if (node.type === 'import') {
    const importNode = new Node(node.path);
    graph.addNode(importNode);
  }
});

// Link the nodes together to form a directed graph representing the import relationships between the Sass files
ast.forEach((node) => {
  if (node.type === 'import') {
    const importNode = new Node(node.path);
    const importedFile = node.importedFile;
    const importedNode = new Node(importedFile.path);
    graph.addEdge(importNode, importedNode);
  }
});
```
This code uses the `sass-parse` library to parse a Sass file and extract a graph of imports by traversing the AST and creating nodes for each import statement. The nodes are then linked together to form a directed graph representing the import relationships between the Sass files.

