const helmet = require('helmet');
const csp = require('helmet-csp');
const scriptIntegrity = require('helmet-script-integrity');

// Customize the default Helmet implementation
const customHelmet = {
  contentSecurityPolicy: (req, res, next) => {
    // Add your own CSP directives here
    const cspDirectives = [
      "default-src 'self'",
      "script-src 'self' 'unsafe-inline' 'unsafe-eval'",
      "style-src 'self' 'unsafe-inline'",
      "img-src 'self' data:",
      "font-src 'self' data:",
      "connect-src 'self'",
      "media-src 'self'",
      "object-src 'none'",
      "frame-ancestors 'none'",
    ];

    // Add the CSP header to the response
    res.setHeader('Content-Security-Policy', cspDirectives.join(';'));
    next();
  },
  scriptIntegrity: (req, res, next) => {
    // Add your own integrity hashes here
    const integrityHashes = [
      "sha256-abcdefg",
      "sha384-hijklmnopqrstuvwxyz",
    ];

    // Add the script integrity header to the response
    res.setHeader('Integrity', integrityHashes.join(', '));
    next();
  },
};

// Create a thread-safe Helmet instance with customized CSP and script integrity validation
const helmetInstance = new helmet(customHelmet);
```
This code creates a thread-safe Helmet instance using the default implementation, but with customized CSP and script integrity validation. The `contentSecurityPolicy` function is used to add custom CSP directives to the response, while the `scriptIntegrity` function is used to add custom integrity hashes to the response. The resulting `helmetInstance` can be used as a middleware in a React 16+ application to provide thread-safe and secure HTTP headers.

