const { createReadStream } = require('fs');
const { pipeline } = require('stream');
const { lint, parse, compile } = require('my-build-system');

async function build(sourceCode) {
  const inputStream = createReadStream(sourceCode);
  const outputStream = new WritableStream();

  // Perform linting and parsing on the source code
  pipeline(inputStream, lint(), parse(), (error) => {
    if (error) {
      console.log('Error during build process:', error);
      return;
    }

    // Compile the parsed code into a bundle of compiled code
    const compiledCode = compile();

    // Output the compiled code in a specific format, such as a tarball or folder of JS files
    outputStream.write(compiledCode);
  });
}
```
