import { React } from 'react';
import { SvgIcon } from '@material-ui/core';
import { reactSvgr } from 'react-svgr';

const MaterialDesignSvgIcons = {};

MaterialDesignSvgIcons.icons = [
  // Add your SVG icons here, using the format:
  // { name: 'icon-name', svg: '<svg>...</svg>' },
];

MaterialDesignSvgIcons.getIconComponent = (name) => {
  const icon = MaterialDesignSvgIcons.icons.find((i) => i.name === name);
  if (!icon) return null;

  // Convert the SVG to a React component using react-svgr
