```
// Wrapper utility for interacting with plist data
const plist = {
  // Reads the contents of a plist file
  read: (filePath) => {
    const fs = require('fs');
    const path = require('path');
    const plistParser = require('plist-parser');

    try {
      const data = fs.readFileSync(filePath, 'utf8');
      return plistParser.parse(data);
    } catch (error) {
      console.log(`Error reading plist file: ${error}`);
      return null;
    }
  },

  // Writes the contents of a plist file
  write: (filePath, data) => {
    const fs = require('fs');
    const path = require('path');
    const plistBuilder = require('plist-builder');

    try {
      const xml = plistBuilder.build(data);
      fs.writeFileSync(filePath, xml, 'utf8');
    } catch (error) {
      console.log(`Error writing plist file: ${error}`);
    }
  },

  // Modifies the contents of a plist file
  modify: (filePath, callback) => {
    const fs = require('fs');
    const path = require('path');
    const plistParser = require('plist-parser');
    const plistBuilder = require('plist-builder');

    try {
      const data = fs.readFileSync(filePath, 'utf8');
      const parsedData = plistParser.parse(data);
      callback(parsedData);
      const modifiedData = plistBuilder.build(parsedData);
      fs.writeFileSync(filePath, modifiedData, 'utf8');
    } catch (error) {
      console.log(`Error modifying plist file: ${error}`);
    }
  },
};
```

