const { Command } = require('@salesforce/command');
const { Messages } = require('@salesforce/core');
const { Sfdx } = require('@salesforce/sfdx');

// Initialize Messages
Messages.importMessagesDirectory(__dirname);

// Define command metadata
const messages = Messages.loadMessages('my-plugin', 'create');
const createCommand = new Command()
  .description(messages.getMessage('commandDescription'))
  .option('--name <value>', messages.getMessage('nameOptionDescription'))
  .option('--type <value>', messages.getMessage('typeOptionDescription'))
  .action((context) => {
    // Create record using Sfdx module
    const sfdx = new Sfdx();
    const record = {
      Name: context.flags.name,
      Type: context.flags.type,
    };
    return sfdx.createRecord(record);
  });

// Define retrieve metadata command
const messagesRetrieveMetadata = Messages.loadMessages('my-plugin', 'retrieve');
const retrieveCommand = new Command()
  .description(messagesRetrieveMetadata.getMessage('commandDescription'))
  .option('--type <value>', messagesRetrieveMetadata.getMessage('typeOptionDescription'))
  .action((context) => {
    // Retrieve metadata using Sfdx module
    const sfdx = new Sfdx();
    return sfdx.retrieveMetadata(context.flags.type);
  });

// Define interact with external service command
const messagesInteractWithExternalService = Messages.loadMessages('my-plugin', 'interact');
const interactCommand = new Command()
  .description(messagesInteractWithExternalService.getMessage('commandDescription'))
  .option('--url <value>', messagesInteractWithExternalService.getMessage('urlOptionDescription'))
  .action((context) => {
    // Interact with external service using HTTP requests
    const url = context.flags.url;
    return fetch(url);
  });

// Define plugin commands
const pluginCommands = [createCommand, retrieveCommand, interactCommand];

// Export plugin commands
module.exports = {
  pluginCommands,
};
```
