const https = require('https');
const { ALPNProtocol } = require('alpn-protocol');

class HTTP2Client extends http.Client {
  constructor(options) {
    super(options);
    this.alpnProtocol = new ALPNProtocol(['h2', 'http/1.1']);
  }

  request(options, callback) {
    const protocol = this.alpnProtocol.select();
    if (protocol === 'h2') {
      return https.request(options, callback);
    } else {
      return http.request(options, callback);
    }
  }
}
```
This code defines a new class called `HTTP2Client` that extends the built-in `http.Client` class in Node.js. The constructor takes an options object as input and sets up an instance of the `ALPNProtocol` class to handle ALPN negotiation.

The `request()` method is overridden to first select the appropriate protocol using the `alpnProtocol.select()` method, which returns either 'h2' or 'http/1.1'. If the selected protocol is 'h2', it uses the `https` module to make an HTTPS request, otherwise it uses the `http` module to make an HTTP request.

This code allows developers to write standard Node.js code that makes HTTP requests to both HTTP/1.x and HTTP/2 servers using the ALPN protocol, transparently taking advantage of improved performance and security benefits of HTTP/2.

