const { Buffer } = require('buffer');
const base64 = require('base64-js');
const base32 = require('base32-js');
const base16 = require('base16-js');

function encode(data, encoding) {
  switch (encoding) {
    case 'base64':
      return Buffer.from(data).toString('base64');
    case 'base32':
      return base32.encode(Buffer.from(data));
    case 'base16':
      return base16.encode(Buffer.from(data));
    default:
      throw new Error(`Unsupported encoding type: ${encoding}`);
  }
}

function decode(data, encoding) {
  switch (encoding) {
    case 'base64':
      return Buffer.from(data, 'base64').toString();
    case 'base32':
      return base32.decode(Buffer.from(data));
    case 'base16':
      return base16.decode(Buffer.from(data));
    default:
      throw new Error(`Unsupported encoding type: ${encoding}`);
  }
}

module.exports = { encode, decode };

