const { NodeTracerProvider } = require('@opentelemetry/node');
const { SimpleSpanProcessor } = require('@opentelemetry/tracing');
const { HttpTraceExporter } = require('@opentelemetry/exporter-http');

// Create a new tracer provider
const tracerProvider = new NodeTracerProvider();

// Set up the trace exporter
const httpTraceExporter = new HttpTraceExporter({
  url: 'https://example.com/trace',
});

// Register the tracer provider with the HTTP server
http.createServer((req, res) => {
  const span = tracerProvider.startSpan('handle-request');
  try {
    // Handle the request
    res.end('Hello World!');
  } catch (err) {
    span.setStatus({ code: SpanStatusCode.ERROR });
    span.recordException(err);
  } finally {
    span.end();
  }
}).listen(8080, () => {
  console.log('Server listening on port 8080');
