Here is an example of how you could create a full-stack web application using Vue.js and TypeScript, with a focus on performance and production-grade quality, utilizing a flexible and modular architecture for easy extension and customization:
```
// Create a new Vue.js project
vue create my-app

// Install the necessary dependencies
npm install --save vuex vue-router @types/vuex @types/vue-router

// Set up the router
const router = new VueRouter({
  mode: 'history',
  routes: [
    { path: '/', component: Home },
    { path: '/about', component: About }
  ]
})

// Create a new TypeScript file for the store
touch store.ts

// Define the store and its actions
const store = createStore({
  state: {
    count: 0
  },
  mutations: {
    increment(state) {
      state.count++
    }
  },
  actions: {
    async fetchData() {
      const response = await fetch('https://api.example.com/data')
      return response.json()
    }
  }
})

// Create a new TypeScript file for the components
touch Home.tsx

// Define the home component
const Home = () => {
  const count = useStore(state => state.count)
  return (
    <div>
      <h1>Home</h1>
      <p>Count: {count}</p>
    </div>
  )
}

// Create a new TypeScript file for the about component
touch About.tsx

// Define the about component
const About = () => {
  return (
    <div>
      <h1>About</h1>
      <p>This is the about page.</p>
    </div>
  )
}

// Create a new TypeScript file for the App.vue component
touch App.tsx

// Define the App.vue component
const App = () => {
  return (
    <div>
      <h1>My App</h1>
      <router-view />
    </div>
  )
}
```
