```
const { decorate } = require('@node-decorators/core');

// Required property decorator
function required(target, key) {
  const descriptor = Object.getOwnPropertyDescriptor(target, key);
  if (descriptor && !descriptor.writable) {
    throw new Error(`Cannot apply @Required to a read-only property`);
  }
  return decorate(target, key, {
    required: true,
    transform: value => value,
  });
}

// Optional property decorator
function optional(target, key) {
  const descriptor = Object.getOwnPropertyDescriptor(target, key);
  if (descriptor && !descriptor.writable) {
    throw new Error(`Cannot apply @Optional to a read-only property`);
  }
  return decorate(target, key, {
    required: false,
    transform: value => value,
  });
}

// Restricted property decorator
function restricted(target, key) {
  const descriptor = Object.getOwnPropertyDescriptor(target, key);
  if (descriptor && !descriptor.writable) {
    throw new Error(`Cannot apply @Restricted to a read-only property`);
  }
  return decorate(target, key, {
    required: true,
    transform: value => value,
    restricted: true,
  });
}

// Transform property decorator
function transform(transformer) {
  return function (target, key) {
    const descriptor = Object.getOwnPropertyDescriptor(target, key);
    if (descriptor && !descriptor.writable) {
      throw new Error(`Cannot apply @Transform to a read-only property`);
    }
    return decorate(target, key, {
      required: true,
      transform: value => transformer(value),
    });
  };
}

// Custom property decorator
function custom(validator) {
  return function (target, key) {
    const descriptor = Object.getOwnPropertyDescriptor(target, key);
    if (descriptor && !descriptor.writable) {
      throw new Error(`Cannot apply @Custom to a read-only property`);
    }
    return decorate(target, key, {
      required: true,
      transform: value => validator(value),
    });
  };
}

// Computed property decorator
function computed(getter) {
  return function (target, key) {
    const descriptor = Object.getOwnPropertyDescriptor(target, key);
    if (descriptor && !descriptor.writable) {
      throw new Error(`Cannot apply @Computed to a read-only property`);
    }
    return decorate(target, key, {
      required: true,
      transform: value => getter(value),
    });
  };
}
```
This code defines several property decorators that can be used to validate and transform properties in a Node.js application. The `required` decorator marks a property as required, while the `optional` decorator marks it as optional. The `restricted` decorator marks a property as restricted, which means that it must have a value when the object is created.

The `transform` decorator allows you to specify a function that will be called with the property's value whenever it is accessed or modified. This can be used to perform additional validation or transformation on the property's value.

The `custom` decorator allows you to specify a custom validator function that will be called with the property's value whenever it is accessed or modified. This can be used to perform any kind of validation or transformation on the property's value.

The `computed` decorator allows you to specify a getter function that will be called whenever the property's value is accessed. This can be used to compute the property's value dynamically based on other properties or data sources.

