    return crypto.createSign('ECDSA-SHA256').update(data).sign(key);
  } else if (key.type === 'dsa') {
    return crypto.createSign('DSA-SHA256').update(data).sign(key);
  }
}

function verify(data, signature, key) {
  // Use the appropriate algorithm based on the key type
  if (key.type === 'rsa') {
    return crypto.createVerify('RSA-SHA256').update(data).verify(signature, key);
  } else if (key.type === 'ecdsa') {
    return crypto.createVerify('ECDSA-SHA256').update(data).verify(signature, key);
  } else if (key.type === 'dsa') {
    return crypto.createVerify('DSA-SHA256').update(data).verify(signature, key);
  }
}

