// Connect to the MySQL database
sql.connect({
  host: 'localhost',
  user: 'your_username',
  password: 'your_password',
  database: 'your_database'
});

// Execute a SQL query
const results = sql.query('SELECT * FROM your_table');

// Get the number of rows affected, inserted, updated, and deleted
const numRowsAffected = results.affectedRows;
const numRowsInserted = results.insertId;
const numRowsUpdated = results.changedRows;
const numRowsDeleted = 0; // No rows were deleted in this example

// Get the query execution time
const queryTime = results.queryTime;

console.log(`Number of rows affected: ${numRowsAffected}`);
console.log(`Number of rows inserted: ${numRowsInserted}`);
console.log(`Number of rows updated: ${numRowsUpdated}`);
console.log(`Number of rows deleted: ${numRowsDeleted}`);
console.log(`Query execution time: ${queryTime} seconds`);
```

