  .append("svg")
  .attr("width", "100%")
  .attr("height", "100%")
  .call(responsive);

// Generate an Irwin-Hall distribution
var n = 10000, // number of trials
    m = 10, // number of random variables
    data = [];
for (var i = 0; i < n; i++) {
  var x = Math.random() * m;
  data.push(x);
}

// Create a histogram using the Irwin-Hall distribution
svg.append("g")
  .attr("transform", "translate(0, 10)")
  .selectAll("rect")
  .data(data)
  .enter()
  .append("rect")
  .attr("x", function(d) { return d * 10; })
  .attr("y", 0)
  .attr("width", 10)
  .attr("height", function(d) { return Math.sqrt(d); });
```
