const domain = 'example.com';

dns.resolve(domain, (err, addresses) => {
  if (err) {
    console.error(err);
    return;
  }

  // Get a list of all subdomains for the given domain
  const subdomains = addresses.filter((address) => address.endsWith('.' + domain));

