response_prompt:
To log data or messages to the console in an Electron app, you can use the `console` object provided by Node.js. In your case, you can use `console.log()` to print a message to the console.

Here's an example of how you can modify your code to use `console.log()`:
```javascript
var app = require('app');
var BrowserWindow = require('browser-window');

require('crash-reporter').start();

var mainWindow = null;

app.on('window-all-closed', function() {
  // Mac OS X - close is done explicitly with Cmd + Q, not just closing windows
  if (process.platform != 'darwin') {
    app.quit();
  }
});

app.on('ready', function(){
  mainWindow = new BrowserWindow({ width: 800, height: 600});

  mainWindow.loadUrl('file://' + __dirname + '/index.html');

  console.log("Hello World!"); // Log a message to the console

  mainWindow.openDevTools();

  mainWindow.on('closed', function(){
    mainWindow = null;
  });
});
```
In this example, we've added a call to `console.log()` after creating the `mainWindow` object. This will print the message "Hello World!" to the console when the app is ready.

Note that you can also use other methods provided by the `console` object, such as `console.error()`, `console.warn()`, and `console.info()`, to log different types of messages to the console.

