How can I mock out hurp and durp so I can effectively unit test?

response_prompt:
You can use the `define` method in RequireJS to define a mock module for Hurp and Durp, like this:
```
define('hurp', function() {
  return {
    beans: 'mock beans'
  };
});

define('durp', function() {
  return {
    beans: 'mock beans'
  };
});
```
This will define two mock modules, `hurp` and `durp`, that contain a single property called `beans`. You can then use these mock modules in your unit tests to replace the actual dependencies of your AMD module.

For example, if you want to test the `foo` function of your AMD module, you could do something like this:
```
define(['hurp', 'durp'], function(Hurp, Durp) {
  var mockHurp = require('hurp');
  var mockDurp = require('durp');

  describe('foo', function() {
    it('should log the beans of Hurp and Durp', function() {
      spyOn(mockHurp, 'beans').and.returnValue('mock beans');
      spyOn(mockDurp, 'beans').and.returnValue('mock beans');

      var module = require('your-amd-module');
      module.foo();

      expect(mockHurp.beans).toHaveBeenCalled();
      expect(mockDurp.beans).toHaveBeenCalled();
    });
  });
});
```
This will define a mock module for Hurp and Durp, and then use these mock modules in your unit test to replace the actual dependencies of your AMD module. The `spyOn` method is used to create spies for the `beans` property of the mock modules, which can be used to verify that the correct methods are being called.

