You can also use the `findRecord` method provided by Ember Data to reload a specific record. Here's an example of how to do it:
```
// Assuming you have a model called "MyRecord" and a route called "my-record"
import Route from '@ember/routing/route';
import { inject as service } from '@ember/service';

export default class MyRecordRoute extends Route {
  @service store;

  model(params) {
    return this.store.find('my-record', params.id);
