  // Handle the conflicts here, for example by updating the conflicting rows
  console.log(conflicts);
};

// Use the knex-conflict package to handle conflicts with batch inserts
db.batchInsert(payload, "payments", 1000)
  .onConflict("batch_id")
  .merge()
  .returning("*")
  .catch((error) => {
    // Handle the error here, for example by logging it to the console
