          return null
        }
      },
      async profile(profile) {
        const { email, firstName, lastName } = profile

        try {
          await connectToDb()

          const user = await User.findOne({ email })

          if(!user) {
            return null
          }

          const passwordsMatch = await bcrypt.compare(password, user.password)

          if(!passwordsMatch) {
