    signIn: '/login'
  }
}

const handler = NextAuth(authOptions)

export { handler as GET, handler as POST}
```
This code uses the `OAuthProvider` to authenticate users based on their email and password. It also includes a `profile` function that allows you to specify additional information about the user, such as their first name and last name. This information is then returned in the session data when the user logs in.

