  }

  callback();
});

// Define your Gulp task that uses the Transform stream
gulp.task('my-task', function () {
  return gulp.src('src/*.txt')
    .pipe(parallel([
      myTransformStream,
      // Add more transform streams here
    ]));
});
```
In this example, we're using `gulp-parallel` to run multiple transform streams in parallel within a pipeline. This allows us to process both files simultaneously, resulting in the output you were expecting:
```
