        date={date}
        onChange={(event) => {
          setDate(event.nativeEvent.timestamp);
        }}
      />
    </View>
  );
};
```
In this example, we are using the `useState` hook to store the current date in the component's state. We then pass the `date` prop to the `DatePickerAndroid` component, which will be used to set the initial value of the picker. The `onChange` prop is called whenever the user selects a new date, and it updates the `date` state variable with the selected date.

