const { Client } = require('elastic-agent');
const { KibanaClient } = require('kibana-cli');
const { ElasticsearchClient } = require('elasticsearch-js');

// Create a new Elastic Agent client
const agentClient = new Client({
  url: 'http://localhost:9243',
});

// Create a new Kibana client
const kibanaClient = new KibanaClient({
  url: 'http://localhost:5602',
});

// Create a new Elasticsearch client
const esClient = new ElasticsearchClient({
  host: 'http://localhost:9201',
});

// Get the service token from Kibana
kibanaClient.getServiceToken().then((token) => {
  // Use the service token to authenticate with Elastic Cloud
  agentClient.authenticate(token).then(() => {
    // Create a new data stream for APM Server
    esClient.createDataStream('apm-server', {
      mappings: {
        properties: {
          '@timestamp': { type: 'date' },
          message: { type: 'text' },
        },
      },
    }).then(() => {
      // Start the Fleet Server
      agentClient.startFleetServer().then(() => {
        console.log('Fleet Server started');
      });
    });
  });
});
```
This code creates a new Elastic Agent client, Kibana client, and Elasticsearch client, and then uses the Kibana client to get the service token from Kibana. It then uses the service token to authenticate with Elastic Cloud, and creates a new data stream for APM Server using the Elasticsearch client. Finally, it starts the Fleet Server using the Elastic Agent client.

